  PhoneAudioSession PhoneMatch(string id,bool fresh=false){if(inventory==null)return null;var identities=inventory.BluetoothDevices.Where(p=>p.Address==PhoneService.Address(id)).ToArray();if(identities.Length!=1||inventory.BluetoothDevices.Count(p=>p.Name==identities[0].Name)!=1)return null;string pattern="(?:^|\\()"+System.Text.RegularExpressions.Regex.Escape(identities[0].Name)+" A2DP SNK\\)?$";var candidates=(fresh?PhoneSessionVolume.List():audioObservation.Phones).Where(s=>s.State!=2&&s.ProcessId>0&&System.Text.RegularExpressions.Regex.IsMatch(s.Name??"",pattern)&&System.Text.RegularExpressions.Regex.IsMatch(s.Identifier??"",@"\\Windows\\System32\\svchost\.exe%b",System.Text.RegularExpressions.RegexOptions.IgnoreCase)).ToArray();return candidates.Length==1?candidates[0]:null;}
  async Task TogglePhoneConnection(string id){try{var session=phones.Get(id);if(session.Connected){await routes.DisconnectPhone(id);}else await routes.ConnectPhone(id);}finally{RenderDevices();UpdateGraphStatus();}}
  void SetPhoneLevel(string id,float? volume,bool? mute){if(routes.Busy)return;var s=phones.Get(id);if(s.Managed){var level=routes.Engine.GetPhoneLevel(id);if(level==null)throw new InvalidOperationException("Phone input unavailable");routes.Engine.SetPhoneLevel(id,volume??level.Volume,mute??level.Muted);}else{var level=PhoneMatch(id,true);if(level==null)throw new InvalidOperationException(L("请播放手机媒体后重试","Play phone media and retry"));if(volume.HasValue)PhoneSessionVolume.SetVolume(level.Endpoint,level.Instance,level.Name,level.ProcessId,volume.Value);if(mute.HasValue)PhoneSessionVolume.SetMute(level.Endpoint,level.Instance,level.Name,level.ProcessId,mute.Value);}}
  void PollDevices(){bool prior=rendering;rendering=true;try{if(!settings.Test){foreach(var pair in outputChecks)try{pair.Value.IsChecked=audioObservation.DefaultId==pair.Key&&!ObservedLevel(pair.Key).Muted;}catch{}foreach(var pair in micChecks)try{pair.Value.IsChecked=!ObservedLevel(pair.Key).Muted;}catch{}
    foreach(var pair in phoneControls)try{float volume;bool muted;var s=phones.Get(pair.Key);bool known=false;if(s.Managed){var level=routes.Engine.GetPhoneLevel(pair.Key);known=level!=null;volume=known?level.Volume:1;muted=known&&level.Muted;}else{var level=PhoneMatch(pair.Key);known=level!=null;volume=known?level.Volume:1;muted=known&&level.Muted;}pair.Value.Enabled.IsEnabled=known;pair.Value.Enabled.IsChecked=!muted;pair.Value.Row.Visibility=known?Visibility.Visible:Visibility.Collapsed;if(!pair.Value.Volume.IsMouseCaptureWithin&&!pair.Value.Volume.IsKeyboardFocusWithin)pair.Value.Volume.Value=Math.Round(volume*100);}catch{}
   }foreach(var refresh in muteRefreshers)refresh();Support();}finally{rendering=prior;}}
